import React from "react";
import image from "./mercury-11591_640.png";

function Mercury({ id }) {
  return (
    <div id={id} className="pt-10 flex flex-col h-screen">
      <h1 className={`text-4xl ob mb-5 text-yellow-400 `}>Mercury</h1>
      <img src={image} alt="" className=" object-contain md:w-1/2" />
    
    </div>
  );
}

export default Mercury;
